def over_summary(balls):
    # balls is a list of runs, for example [1, 4, 0, 6, 2, 1]
    # Return (total_runs, big_hits)
    total_runs = 0
    big_hits = 0
    # simple loop over the list
    for run in balls:
        total_runs = total_runs + run
        if run >= 6:
            big_hits = big_hits + 1
    # return the tuple
    return (total_runs, big_hits)

print(over_summary([1, 4, 0, 6, 2, 1]))

